messages.content:
module fluorescence

manifest tissue_biopsy
manifest fixative
manifest dapi_stain
manifest gfap_antibody
manifest neun_antibody
manifest lysis_buffer

instructions:

// Steps 1-2: mount 2 mm cryosectioned tissue biopsy on the tDISCO top-plate and fix it on-chip
biopsy = dispense tissue_biopsy
fix = dispense fixative
fixed_tissue = mix biopsy with fix for 900s
dispose fix

// Step 3: on-chip immunostaining (DAPI nuclei, GFAP astrocyte marker, NEUN neuronal marker)
dapi = dispense dapi_stain
stain1 = mix fixed_tissue with dapi for 300s
gfap = dispense gfap_antibody
stain2 = mix stain1 with gfap for 600s
neun = dispense neun_antibody
stained_tissue = mix stain2 with neun for 600s

// Steps 4-5: AI/image-based mapping and selection of a single target cell
// (e.g., a DAPI+/GFAP+ astrocyte at a defined distance from the stroke lesion)
selection_signal = detect fluorescence on stained_tissue for 10s

if (selection_signal >= 80) {
    // Steps 6-9: iterative single-cell isolation from the same tissue section:
    // position a receiving-buffer droplet over the selected cell, laser-lyse it,
    // collect the lysate droplet, replenish buffer, and repeat for the next target cell
    repeat 3 times {
        buffer = dispense 1 units of lysis_buffer
        positioned_droplet = mix stained_tissue with buffer for 5s
        cell_lysate = heat positioned_droplet at 25c for 1s
        dispose cell_lysate
    }
} else {
    dispose stained_tissue
}
